<script setup>
import {fuzzyMatch} from '../../shared/search.mjs';
import {ref,computed,onMounted} from 'vue';
import {PanelsTopLeft,RefreshCw,Trash2,Undo2,X,LoaderCircle} from 'lucide-vue-next';
import {useStudio,api} from '../store';
const s=useStudio(),emit=defineEmits(['close']),query=ref(''),trash=ref([]),refreshing=ref(false),deleting=ref(null),working=ref(false),showTrash=ref(false);
const projects=computed(()=>s.projects.filter(p=>fuzzyMatch(query.value,p.name)));
async function refresh(){refreshing.value=true;try{await s.refreshCollections();trash.value=await api('projects/trash');}finally{refreshing.value=false;}}
async function remove(){if(working.value)return;working.value=true;try{const result=await s.deleteProject(deleting.value.id);trash.value=result.trash;deleting.value=null;s.notify('项目已移入本地回收区');}finally{working.value=false;}}
async function restore(p){if(working.value)return;working.value=true;try{const d=await api('projects/restore',{id:p.id});s.projects=d.projects;trash.value=d.trash;s.notify('已恢复 '+p.name);}finally{working.value=false;}}
onMounted(()=>s.action(refresh));
</script>
<template><div class="modal-backdrop" @click.self="emit('close')"><section class="modal project-browser" role="dialog" aria-label="本地漫画项目"><div class="modal-dismiss-row"><button class="icon-button" title="关闭项目列表" @click="emit('close')"><X :size="19"/></button></div><div class="modal-title"><h2>本地漫画项目</h2><button class="secondary" :disabled="refreshing" :aria-busy="refreshing" @click="s.action(refresh)"><RefreshCw :size="15"/>刷新项目列表</button></div><input v-model="query" placeholder="模糊查找项目名称" aria-label="模糊查找项目名称"/><div class="project-browser-list"><div v-for="p in projects" :key="p.id" class="project-browser-row"><button class="project-entry" :title="p.name" @click="s.action(async()=>{await s.openProject(p.id);emit('close')})"><PanelsTopLeft :size="18"/><strong>{{p.name}}</strong><span>{{p.pages}} 页</span><small>{{new Date(p.updated).toLocaleString()}}</small></button><button class="icon-button danger" :title="'删除项目：'+p.name" :aria-label="'删除项目：'+p.name" @click="deleting=p"><Trash2 :size="17"/></button></div><p v-if="!projects.length" class="empty">{{query?'没有匹配的项目':'暂无已保存项目'}}</p></div><button class="quiet" @click="showTrash=!showTrash"><Trash2 :size="14"/>本地回收区（{{trash.length}}）</button><div v-if="showTrash" class="project-trash-list"><div v-for="p in trash" :key="p.id" class="button-row"><span :title="p.name">{{p.name}}</span><button class="quiet push" :disabled="working" @click="s.action(()=>restore(p))"><Undo2 :size="14"/>恢复</button></div><p v-if="!trash.length" class="muted">回收区为空。</p></div></section><div v-if="deleting" class="modal-backdrop" @click.self="!working&&(deleting=null)"><section class="modal confirm-modal" role="dialog" aria-label="确认删除项目"><div class="modal-dismiss-row"><button class="icon-button" aria-label="关闭项目删除确认" @click="deleting=null"><X :size="20"/></button></div><div class="modal-title"><h2>删除项目</h2></div><p>将“{{deleting.name}}”移入本地回收区？可在项目列表中恢复。</p><div class="button-row"><button class="secondary" :disabled="working" @click="deleting=null">取消</button><button class="primary" :disabled="working" @click="s.action(remove)"><LoaderCircle v-if="working" class="spin" :size="15"/><Trash2 v-else :size="15"/>移入回收区</button></div></section></div></div></template>
